def F_two_value(a):
    b = 0.5 - a
    if a < 0 or b < 0:
        return None

    term1 = 1 / (16 * a**3 + 1)
    term2 = 1 / (16 * b**3 + 1)

    return 0.5 * (term1 + term2)

# Test points
test_a_values = [0, 1/12, 1/8, 1/6, 1/4]

results = {}
for a in test_a_values:
    results[a] = F_two_value(a)

print("Test results:")
for a, val in results.items():
    print(f"a={a:.4f}, b={0.5-a:.4f}, F = {val}")

